//! FFI bindings for bitnet.cpp
//!
//! This crate provides Rust bindings to the bitnet.cpp C API.
//! Generated by bindgen from bitnet.h.

#![allow(non_camel_case_types, non_snake_case, non_upper_case_globals)]
#![cfg_attr(bitnet_unavailable, allow(dead_code, unused_imports, unused_variables))]

use libc::{c_char, c_int, c_void, size_t};

#[cfg(not(bitnet_unavailable))]
include!(concat!(env!("OUT_DIR"), "/bindings.rs"));

#[cfg(bitnet_unavailable)]
mod stubs {
    use libc::{c_char, c_int, c_void};
    
    pub type bitnet_context = c_void;
    pub type bitnet_token = c_int;
    
    pub unsafe fn bitnet_init(_model_path: *const c_char, _n_threads: c_int) -> *mut bitnet_context {
        std::ptr::null_mut()
    }
    
    pub unsafe fn bitnet_free(_ctx: *mut bitnet_context) {}
    
    pub unsafe fn bitnet_infer(
        _ctx: *mut bitnet_context,
        _input_ids: *const bitnet_token,
        _n_tokens: c_int,
        _output_logits: *mut f32,
        _n_vocab: c_int,
    ) -> c_int {
        -1
    }
    
    pub unsafe fn bitnet_tokenize(
        _ctx: *mut bitnet_context,
        _text: *const c_char,
        _tokens: *mut bitnet_token,
        _max_tokens: c_int,
    ) -> c_int {
        -1
    }
    
    pub unsafe fn bitnet_detokenize(
        _ctx: *mut bitnet_context,
        _tokens: *const bitnet_token,
        _n_tokens: c_int,
        _text: *mut c_char,
        _max_text: c_int,
    ) -> c_int {
        -1
    }
    
    pub unsafe fn bitnet_n_vocab(_ctx: *mut bitnet_context) -> c_int {
        32000
    }
    
    pub unsafe fn bitnet_n_ctx(_ctx: *mut bitnet_context) -> c_int {
        2048
    }
}

#[cfg(bitnet_unavailable)]
pub use stubs::*;

/// Safe wrapper around bitnet context
#[derive(Debug)]
pub struct BitNetContext {
    ctx: *mut bitnet_context,
    n_vocab: i32,
    n_ctx: i32,
}

impl BitNetContext {
    /// Load a bitnet model
    pub fn load(model_path: &str, n_threads: i32) -> Result<Self, BitNetError> {
        #[cfg(bitnet_unavailable)]
        return Err(BitNetError::Unavailable);
        
        #[cfg(not(bitnet_unavailable))]
        {
            use std::ffi::CString;
            let c_path = CString::new(model_path).map_err(|_| BitNetError::InvalidPath)?;
            let ctx = unsafe { bitnet_init(c_path.as_ptr(), n_threads) };
            if ctx.is_null() {
                return Err(BitNetError::LoadFailed);
            }
            let n_vocab = unsafe { bitnet_n_vocab(ctx) };
            let n_ctx = unsafe { bitnet_n_ctx(ctx) };
            Ok(Self { ctx, n_vocab, n_ctx })
        }
    }
    
    /// Run inference
    pub fn infer(&self, input_ids: &[i32]) -> Result<Vec<f32>, BitNetError> {
        #[cfg(bitnet_unavailable)]
        return Err(BitNetError::Unavailable);
        
        #[cfg(not(bitnet_unavailable))]
        {
            if input_ids.len() > self.n_ctx as usize {
                return Err(BitNetError::ContextOverflow);
            }
            
            let mut output = vec![0.0f32; self.n_vocab as usize];
            let ret = unsafe {
                bitnet_infer(
                    self.ctx,
                    input_ids.as_ptr(),
                    input_ids.len() as c_int,
                    output.as_mut_ptr(),
                    self.n_vocab,
                )
            };
            
            if ret != 0 {
                return Err(BitNetError::InferenceFailed(ret));
            }
            
            Ok(output)
        }
    }
    
    /// Tokenize text
    pub fn tokenize(&self, text: &str) -> Result<Vec<i32>, BitNetError> {
        #[cfg(bitnet_unavailable)]
        return Err(BitNetError::Unavailable);
        
        #[cfg(not(bitnet_unavailable))]
        {
            use std::ffi::CString;
            let c_text = CString::new(text).map_err(|_| BitNetError::InvalidInput)?;
            let mut tokens = vec![0i32; self.n_ctx as usize];
            let n_tokens = unsafe {
                bitnet_tokenize(
                    self.ctx,
                    c_text.as_ptr(),
                    tokens.as_mut_ptr(),
                    self.n_ctx,
                )
            };
            
            if n_tokens < 0 {
                return Err(BitNetError::TokenizationFailed(n_tokens));
            }
            
            tokens.truncate(n_tokens as usize);
            Ok(tokens)
        }
    }
    
    /// Detokenize tokens
    pub fn detokenize(&self, tokens: &[i32]) -> Result<String, BitNetError> {
        #[cfg(bitnet_unavailable)]
        return Err(BitNetError::Unavailable);
        
        #[cfg(not(bitnet_unavailable))]
        {
            let mut text = vec![0u8; 4096];
            let len = unsafe {
                bitnet_detokenize(
                    self.ctx,
                    tokens.as_ptr(),
                    tokens.len() as c_int,
                    text.as_mut_ptr() as *mut c_char,
                    text.len() as c_int,
                )
            };
            
            if len < 0 {
                return Err(BitNetError::DetokenizationFailed(len));
            }
            
            String::from_utf8(text[..len as usize].to_vec())
                .map_err(|_| BitNetError::InvalidUtf8)
        }
    }
    
    pub fn n_vocab(&self) -> usize { self.n_vocab as usize }
    pub fn n_ctx(&self) -> usize { self.n_ctx as usize }
}

impl Drop for BitNetContext {
    fn drop(&mut self) {
        #[cfg(not(bitnet_unavailable))]
        unsafe { bitnet_free(self.ctx) };
    }
}

unsafe impl Send for BitNetContext {}
unsafe impl Sync for BitNetContext {}

#[derive(Debug, thiserror::Error)]
pub enum BitNetError {
    #[error("bitnet.cpp not available (compile with bitnet feature)")]
    Unavailable,
    #[error("Invalid model path")]
    InvalidPath,
    #[error("Failed to load model")]
    LoadFailed,
    #[error("Input exceeds context window")]
    ContextOverflow,
    #[error("Inference failed with code {0}")]
    InferenceFailed(i32),
    #[error("Tokenization failed with code {0}")]
    TokenizationFailed(i32),
    #[error("Detokenization failed with code {0}")]
    DetokenizationFailed(i32),
    #[error("Invalid UTF-8 in output")]
    InvalidUtf8,
    #[error("Invalid input")]
    InvalidInput,
}

